const uri=source=>'data:text/javascript;base64,'+Buffer.from(source).toString('base64');
async function loadHarness(source,moduleSource){
 // Expose the real closure only to inspect retained draft identity and to inject
 // adversarial mutations. Production functions and all state transitions run unchanged.
 moduleSource=replace(moduleSource,'return {panel,details,setup,search,manual,board,deliver,auditOffer,clear};','return {testSnapshot:()=>({drafts,searchId}),testSet:(d,id)=>{drafts=d;searchId=id;},panel,details,setup,search,manual,board,deliver,auditOffer,clear};');
 const pu=uri(absolutize(moduleSource,passengerURL));
 source=source.replace(/^import \{createPassengerUI\} from '[^']+';/m,"import {createPassengerUI} from '"+pu+"';");
 let hs=await readFile(harnessURL,'utf8');
 hs=replace(hs,"const app=await readFile(new URL('../js/app.mjs',import.meta.url),'utf8');",'const app=PASSENGER_APP_SOURCE;');
 hs=absolutize(hs,harnessURL);hs=replace(hs,'PASSENGER_APP_SOURCE',JSON.stringify(source));
 hs=replace(hs,'globalThis.api={setStore',"globalThis.api={setDecisions(value){decisions=value;},get tab(){return tab;},refreshNearby,get coreRules(){return core;},setCoreRules(value){core=value;},get passengers(){return passengers;},get passengerOwner(){return typeof passengerWriteOperation==='undefined'?null:passengerWriteOperation;},completePassengerWrite:typeof completePassengerWrite==='function'?completePassengerWrite:null,roleChange:"+roleCallback+',setStore');
 hs=replace(hs,'priceDice:0','priceDice:0,rolls:0,dice:0,uids:0,nearby:0');
 hs=replace(hs,'roll:n=>({dice:Array(n).fill(3),total:n*3}),die:()=>3','roll:n=>{calls.rolls++;calls.onRoll?.();return bindings.R.roll(n,()=>3);},die:()=>{calls.dice++;calls.onDie?.();return 3;}');
 hs=replace(hs,'const sandbox={...bindings,R:rules,',"const sandbox={...bindings,M:{...bindings.M,nearby(...args){calls.nearby++;return calls.onNearby?.(...args)??Promise.resolve([]);}},S:{...bindings.S,uid(){calls.uids++;calls.onUid?.();return bindings.S.uid();}},R:rules,");
 const hm=uri(hs);let ss=absolutize(await readFile(storageURL,'utf8'),storageURL);ss=replace(ss,JSON.stringify(harnessURL.href),JSON.stringify(hm));
 return (await import(uri(ss))).depositHarness;
}
