function modalButtons(h){return [...body(h).matchAll(/<button\b([^>]*)>/g)].map(m=>element(attrs(m[1])));}
function prepare(h,kind='setup',edits={}){h.api.actions['passenger-'+kind]();h.fill(kind==='setup'?{reservedCabins:2,installedLowBerths:4,reviewed:true,...edits}:{destination:'1,0',dice:12,skill:2,characteristic:1,steward:1,sequence:Array(200).fill(2).join(','),...edits});assert.equal(ui(h).modalError,'');}
const body=h=>h.dom.ids.get('modal-body').innerHTML;
const display=h=>({summary:h.dom.ids.get('summary').innerHTML,main:h.dom.ids.get('main').innerHTML});
const ephemera=h=>({passengers:structuredClone(h.api.passengers.testSnapshot()),drafts:structuredClone(h.api.drafts),check:structuredClone(h.api.check),tab:h.api.tab,view:h.api.view});
