async function pending(t,{h=null,kind='setup',edits={}}={}){h??=setup();const before=structuredClone(h.api.state),raw=h.bytes();prepare(h,kind,edits);const session=h.api.modalSession,review=body(h),visible=display(h),ephemeral=ephemera(h),gate=serviceSaveGate(h.store),detached=h.dom.ids.get('modal-form').onsubmit,operation=h.submit();await flush();assert.equal(gate.entries.length,1,'One production passenger transition reached actual delayed Store');const counts=count(h);t.after(async()=>{for(const e of gate.entries)if(!e.settled)e.fulfill();await operation;gate.restore();});return {h,kind,before,raw,session,review,visible,ephemeral,gate,detached,operation,counts};}
