for(const kind of kinds)test(`baseline red: delayed ${kind} keeps review open and results unpublished until settled`,async t=>{const {h,before,raw,session,review,visible,ephemeral,gate,operation,counts}=await pending(t,{kind});assert.equal(h.bytes(),raw);same(h.api.state,before);same(ephemera(h),ephemeral);assert.equal(ui(h).modalOpen,true,'Review stays open before actual provider write');assert.equal(h.dom.ids.get('modal-close').disabled,true);assert.equal(session.busy,true);assert.equal(session.awaitSave,true);noSuccess(h);gate.entries[0].write();same(h.persisted(),gate.entries[0].args[0]);same(ephemera(h),ephemeral);same(display(h),visible);assert.equal(body(h),review);h.api.render();same(display(h),visible);same(count(h),counts);noSuccess(h);gate.entries[0].fulfill();await operation;assert.equal(h.counters.writes,1);assert.equal(ui(h).modalOpen,false);assert.equal(ui(h).modalError,'');assert.match(ui(h).message,successes[kind]);});
